{"op":"add","path":"/root","value":"navigation_toolbar"}
{"op":"add","path":"/elements/apply_filter_button","value":{"type":"Button","props":{"id":"apply_filter_button","label":"Refresh activity"},"on":{"press":{"action":"ApplyFilter","params":{"target_id":"activity"}}},"children":[]}}
{"op":"add","path":"/elements/activity_panel","value":{"type":"Toolbar","props":{"id":"activity_panel","orientation":"vertical"},"children":["apply_filter_button"]}}
