{"op":"add","path":"/elements/feedback_toast","value":{"type":"Toast","props":{"id":"feedback_toast","tone":{"$state":"/feedback/tone"},"title":{"$state":"/feedback/title"},"message":{"$state":"/feedback/message"}},"children":[]}}
{"op":"add","path":"/state/feedback/tone","value":"success"}
{"op":"add","path":"/state/feedback/title","value":"Saved · variant 1"}
{"op":"add","path":"/state/feedback/message","value":"Your activity view is current. · variant 1"}
